import React, {useState, useContext} from 'react';
import {
  MDBBtn,
  MDBContainer,
  MDBCard,
  MDBCardBody,
  MDBCardImage,
  MDBRow,
  MDBCol,
  MDBIcon,
  MDBInput
}
from 'mdb-react-ui-kit';
import { Button, Form } from 'react-bootstrap';

import AuthContext, {AuthProvider} from '../components/AuthContext';

import {Link} from 'react-router-dom'

function LoginScreen() {
  const [email, setEmail]=useState('')
  const [password, setPassword]=useState('')
  let {loginUser} =useContext(AuthContext)

  return (
    <MDBContainer className="my-5">


      <MDBCard>
        <MDBRow className='g-0'>

          <MDBCol md='6'>
            <MDBCardImage src='https://mdbcdn.b-cdn.net/img/Photos/new-templates/bootstrap-login-form/img1.webp' alt="login form" className='rounded-start w-100'/>
          </MDBCol>

          <MDBCol md='6'>
            <Form className='d-flex flex-column' onSubmit={loginUser}>

              <h5 className="fw-normal my-4 pb-3" style={{letterSpacing: '1px'}}>Sign into your account</h5>

                <input wrapperClass='mb-4' label='Email address' id='formControlLg' type='email' size="lg" value={email} onChange={(e) => setEmail(e.target.value)}/>
                <input wrapperClass='mb-4' label='Password' type='password' size="lg" value={password} onChange={(e) => setPassword(e.target.value)}/>

              <Button className="mb-4 px-5" color='dark' size='lg'>Login</Button>
          
              <p className="mb-5 pb-lg-2" style={{color: '#393f81'}}>Don't have an account? <Link to="/register"> <MDBBtn className="px-5" color='dark' size='sm'>Register</MDBBtn> </Link></p>


            </Form>
          </MDBCol>

        </MDBRow>
      </MDBCard>

    </MDBContainer>
  );
}

export default LoginScreen;
